      'regular_bills','sales_nf_report','service_nf_report',
      'nf_service_labels','nf_service_labels_ids','nf_service_info',
      'employers_general_data','employers_plus','employers_plus_info'
    ]
  }
};

// ─────────────────────────────────────────────
// Respond to Webhook — Serializador universal
// Suporta:
//   body = array  → serializa como JSON array direto
//   body = object → serializa como JSON object
//   body = string → serializa como string
// Preserva statusCode de cada sub-workflow.
// ─────────────────────────────────────────────
const result = $input.first().json;
const statusCode = result.statusCode || 200;
const body = result.body !== undefined ? result.body : result;

return {
  statusCode,
  body
};

// ─────────────────────────────────────────────
// VHSYS Router — Extract Route & Parameters
// Extrai rota lógica, parâmetros de query e monta
// envelope canônico para todos os sub-workflows.
// ─────────────────────────────────────────────
const req   = $input.item.json;
const method = ('PUT').toString().toUpperCase();
const body   = req.body  || {};
const query  = req.query || {};

// Extrair rota de múltiplas fontes possíveis
let route = 'unknown';

// 1. Verificar query parameter ?route=
if (query.route) {
  route = query.route.toString().trim();
} 
// 2. Verificar body.route (para POST)
else if (body.route) {
  route = body.route.toString().trim();
}
// 3. Verificar path da URL (para /webhook/vhsys-router/employers_general_data)
else if (req.params && req.params.path) {
  const pathParts = req.params.path.split('/');
  const lastPart = pathParts[pathParts.length - 1];
  if (lastPart && lastPart !== 'vhsys-router') {
    route = lastPart.toString().trim();
  }
}
// 4. Tentar extrair do webhook path completo
else if (req.webhookUrl || req.url) {
  const url = req.webhookUrl || req.url;
  const match = url.match(/\/([^/?]+)(\?|$)/);
  if (match && match[1] && match[1] !== 'vhsys-router') {
    route = match[1].toString().trim();
  }
}

// Limpar a rota de qualquer parâmetro que possa ter "grudado"
route = route.split('?')[0].split('&')[0];

// Extrair parâmetros específicos comuns
const parameters = {
  rt_token: query.rt_token || 'YfdDQlECBBBXTwAqsrCLU88jds465VbPIevKuZnKLP9N4OwFl',
  // Outros parâmetros podem ser adicionados aqui conforme necessário
};

// Remover parâmetros já extraídos do query object para evitar duplicação
const cleanQuery = { ...query };
delete cleanQuery.route;
delete cleanQuery.rt_token;

// Log estruturado — sem campos sensíveis (mascarar token)
const logData = {
  timestamp: new Date().toISOString(),
  event:     'router_request',
  route,
  method,
  has_body:  Object.keys(body).length > 0,
  has_rt_token: !!parameters.rt_token,
  other_params: Object.keys(cleanQuery).length,
  url: req.webhookUrl || req.url || 'unknown',
  level:     'info'
};

// Log com token mascarado para segurança
if (parameters.rt_token) {
  logData.rt_token_prefix = parameters.rt_token.substring(0, 8) + '...';
}

console.log(JSON.stringify(logData));

return { 
  route, 
  method, 
  body, 
  query: cleanQuery, 
  parameters, 
  original_request: req 
};

